require 'socket'
require 'thread'
require 'digest'
require 'json'

module DistCache
  class ConnectionPool
    def initialize(size: 5)
      @pool = Queue.new
      @size = size
      @monitor = Monitor.new
      @created = 0
    end

    def checkout
      @monitor.synchronize do
        if @pool.empty? && @created < @size
          @created += 1
          return create_connection
        end
      end
      @pool.pop
    end

    def checkin(conn)
      @pool.push(conn)
    end

    private

    def create_connection
      host = ENV.fetch('CACHE_HOST', '127.0.0.1')
      port = ENV.fetch('CACHE_PORT', '11211').to_i
      CacheConnection.new(host, port)
    end
  end

  class CacheConnection
    attr_reader :host, :port

    def initialize(host, port)
      @host = host
      @port = port
      @socket = TCPSocket.new(host, port)
      @mutex = Mutex.new
    end

    def execute(command)
      @mutex.synchronize do
        @socket.write(command + "\r\n")
        read_response
      end
    end

    def alive?
      !@socket.closed?
    end

    def close
      @socket.close unless @socket.closed?
    end

    private

    def read_response
      @socket.gets&.chomp
    end
  end

  class Client
    RETRY_LIMIT = 3

    def initialize(pool: nil, serializer: nil)
      @pool = pool || ConnectionPool.new
      @serializer = serializer || method(:default_serialize)
      @hooks = { before_get: [], after_set: [], on_evict: [] }
      @local_buffer = {}
      @buffer_lock = Mutex.new
      @eviction_policy = ENV.fetch('CACHE_EVICTION_POLICY', 'lru')
      @max_buffer = ENV.fetch('CACHE_LOCAL_BUFFER_SIZE', '100').to_i
      @namespace = ENV.fetch('CACHE_NAMESPACE', '')
    end

    def register_hook(event, &block)
      @hooks[event] << block if @hooks.key?(event)
    end

    def get(key)
      namespaced = apply_namespace(key)
      run_hooks(:before_get, namespaced)

      # Check local buffer first
      cached = buffer_read(namespaced)
      return cached if cached

      result = with_retry do |conn|
        conn.execute("GET #{namespaced}")
      end

      if result && result != 'NOT_FOUND'
        parsed = deserialize(result)
        buffer_write(namespaced, parsed)
        parsed
      else
        nil
      end
    end

    def set(key, value, ttl: 0)
      namespaced = apply_namespace(key)
      serialized = @serializer.call(value)

      result = with_retry do |conn|
        conn.execute("SET #{namespaced} #{ttl} #{serialized.bytesize}\r\n#{serialized}")
      end

      if result == 'STORED'
        buffer_write(namespaced, value)
        run_hooks(:after_set, namespaced, value)
        true
      else
        false
      end
    end

    def delete(key)
      namespaced = apply_namespace(key)
      result = with_retry do |conn|
        conn.execute("DELETE #{namespaced}")
      end
      buffer_delete(namespaced)
      result == 'DELETED'
    end

    def flush_buffer
      @buffer_lock.synchronize do
        @local_buffer.clear
      end
    end

    private

    def apply_namespace(key)
      @namespace.empty? ? key : "#{@namespace}:#{key}"
    end

    def buffer_read(key)
      @buffer_lock.synchronize do
        entry = @local_buffer[key]
        return nil unless entry
        entry[:accessed_at] = Time.now
        entry[:value]
      end
    end

    def buffer_write(key, value)
      @buffer_lock.synchronize do
        evict_if_needed
        @local_buffer[key] = { value: value, accessed_at: Time.now, created_at: Time.now }
      end
    end

    def buffer_delete(key)
      @buffer_lock.synchronize do
        @local_buffer.delete(key)
      end
    end

    def evict_if_needed
      return if @local_buffer.size < @max_buffer

      victim_key = select_victim
      if victim_key
        evicted_value = @local_buffer.delete(victim_key)
        run_hooks(:on_evict, victim_key, evicted_value[:value])
      end
    end

    def select_victim
      case @eviction_policy
      when 'lru'
        @local_buffer.min_by { |_, v| v[:accessed_at] }&.first
      when 'fifo'
        @local_buffer.min_by { |_, v| v[:created_at] }&.first
      else
        @local_buffer.keys.sample
      end
    end

    def run_hooks(event, *args)
      @hooks[event].each { |hook| hook.call(*args) }
    end

    def with_retry
      attempts = 0
      begin
        conn = @pool.checkout
        result = yield conn
        @pool.checkin(conn)
        result
      rescue => e
        attempts += 1
        conn&.close
        retry if attempts < RETRY_LIMIT
        raise
      end
    end

    def default_serialize(value)
      JSON.generate(value)
    end

    def deserialize(data)
      JSON.parse(data)
    end
  end
end
